?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Order | GoldCart</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="brand" href="index.php">GOLD<span>CART</span></a><nav><a href="index.php">Home</a><a href="login.php">Login</a></nav></header><main class="form-wrap"><div class="panel"><p class="eyebrow">ORDER STATUS</p><h1>Track Your Order</h1><form class="form-grid" method="get"><label>Order Number<input name="order" value="<?= htmlspecialchars($orderNo) ?>" placeholder="e.g. GC261021ABC123" required></label><button class="btn">Find Order</button></form><?php if($error): ?><div class="notice"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if($order): ?><div class="notice"><strong><?= htmlspecialchars($order['order_no']) ?></strong><p>Status: <?= htmlspecialchars($order['status']) ?></p><p>Payment: <?= htmlspecialchars($order['payment_status']) ?></p><p>Total: ₹<?= number_format($order['total'],2) ?></p><p class="muted">Placed: <?= htmlspecialchars($order['created_at']) ?></p></div><?php elseif($orderNo!==''&&!$error): ?><p class="muted">Order not found for this account.</p><?php endif; ?></div></main></body></html>
